svg.desc:
// clk rising edge; rst_n synchronous active-low: every register (incl. s_cache) resets to 0, state IDLE.
// Nets with the same label are connected. txn_clr has priority over every other action.
localparam ST_IDLE = 2'd0, ST_PREP = 2'd1, ST_RUN = 2'd2, ST_DONE = 2'd3;
gen_ready = gen_ready_q;
[op_div30]
gh_init = n_id / 10'd30;                                   // 0..34
[u_gold_gh]
pucch_f1_gold_gen u_gold_gh (.start(txn_start), .clr(txn_clr), .c_init({25'd0, gh_init}),
                             .c_valid(gh_valid), .c_bit(gh_bit), .c_idx(gh_idx));
[u_gold_cs]
pucch_f1_gold_gen u_gold_cs (.start(txn_start), .clr(txn_clr), .c_init({21'd0, n_id}),
                             .c_valid(cs_valid), .c_bit(cs_bit), .c_idx(cs_idx));
[blk_cap]
prep    = (state_q == ST_PREP);
gh_base = {3'd0, slot_idx, 4'd0};                         // 16 * slot
gh_off  = gh_idx - gh_base;
gh_hit  = prep & gh_valid & (gh_idx >= gh_base) & (gh_off < 12'd16);
cs_base = slot_idx * 7'd112;                              // 12 bits
cs_off  = cs_idx - cs_base;
cs_hit  = prep & cs_valid & (cs_idx >= cs_base) & (cs_off < 12'd112);
fgh_q[gh_off[3:0]] <= gh_bit @(en=gh_hit);  fgh_q <= 16'd0 on txn_clr | txn_start  @(rst=16'd0)
ncs_byte_q[cs_off[2:0]] <= cs_bit @(en=cs_hit);  ncs_byte_q <= 8'd0 on txn_clr | txn_start  @(rst=8'd0)
n_cs    = {cs_bit, ncs_byte_q[6:0]};                      // completed byte (bit b at position b)
sc_we   = cs_hit & (cs_off[2:0] == 3'd7);
sc_wa   = cs_off[6:3];                                    // absolute symbol l
sc_wd   = ({4'd0, m0} + {1'b0, n_cs}) % 9'd12;            // s_l = (m0 + n_cs) mod 12
prep_done = cs_hit & (cs_off == 12'd111);                 // GH bits always finish earlier
[mem_scache]
reg [3:0] s_cache_q [0:13];
s_cache_q[sc_wa] <= sc_wd @(en=sc_we);  all entries <= 4'd0 on txn_clr | txn_start  @(rst=4'd0)
s_l = (l_abs5 <= 5'd13) ? s_cache_q[l_abs5[3:0]] : 4'd0;
[blk_uq]
f_ss  = n_id % 10'd30;
fgh0  = (gh_mode == 2'd1) ? fgh_q[7:0]  % 8'd30 : 5'd0;
fgh1  = (gh_mode == 2'd1) ? fgh_q[15:8] % 8'd30 : 5'd0;
u0_q <= (f_ss + fgh0) % 30 @(en=prep_done);  u1_q <= (f_ss + fgh1) % 30 @(en=prep_done);  cleared on txn_clr | txn_start  @(rst=5'd0)
[cloud_next]
fire = phase_valid & phase_ready;
state_d = txn_clr ? ST_IDLE : txn_start ? ST_PREP :
          (state_q == ST_PREP & prep_done) ? ST_RUN :
          (state_q == ST_RUN & fire & phase_last) ? ST_DONE : state_q;
gen_ready_d = (txn_clr | txn_start) ? 1'b0 : prep_done ? 1'b1 : gen_ready_q;
[fsm_state]
state_q <= state_d @(rst=ST_IDLE);
[reg_gr]
gen_ready_q <= gen_ready_d @(rst=1'b0);                    // held until txn_clr
[op_run]
phase_valid = (state_q == ST_RUN);
[gate_fire]
fire = phase_valid & phase_ready;
[blk_cursor]
// registers q_q[6:0], g_q[2:0], n_q[3:0], t_q[3:0] @(rst=0); cleared on txn_clr | txn_start
on fire: q_q <= q_q + 7'd1;
         if (n_q == 4'd11) begin n_q <= 4'd0; t_q <= 4'd0; g_q <= g_q + 3'd1; end
         else begin n_q <= n_q + 4'd1; t_sum = {1'b0, t_q} + {1'b0, s_l}; t_q <= (t_sum >= 5'd12) ? t_sum - 5'd12 : t_sum; end
phase_hop      = hopping & (g_q >= n_sf0);
phase_m        = phase_hop ? g_q - n_sf0 : g_q;
l_abs5         = {1'b0, start_symbol} + {1'b0, g_q, 1'b1};  // start + 2g + 1
phase_l_abs    = l_abs5[3:0];
phase_sample_q = q_q;  phase_n = n_q;
phase_first    = (q_q == 7'd0);
phase_last     = (q_q == n_re - 7'd1);
[mux_u]
u_sel = phase_hop ? u1_q : u0_q;
[mem_base]
// constant ROM 360 x 16, addr = 12*u + n, contents = (8192 * phi_u(n)) mod 65536 (source 07 section 2)
base_phase = ((u_sel <= 5'd29) & (n_q <= 4'd11)) ? BASE[12*u_sel + n_q] : 16'd0;
[mem_cs]
// constant ROM 12 x 16, CS[t] = floor(65536 * t / 12) (source 07 section 4)
cs_phase = (t_q <= 4'd11) ? CS[t_q] : 16'd0;
[op_radd]
r_phase = base_phase + cs_phase;                          // modulo 65536
[cloud_luterr]
lut_err = phase_valid & ((u_sel > 5'd29) | (n_q > 4'd11) | (t_q > 4'd11) | (l_abs5 > 5'd13));
